function [pull] = flex_pull(f, eta, etad)
%FLEX_PULL  The mode's restoring and damping force on its coordinate, 2 zeta Omega etad + Omega^2 eta, which acts on the body
%   through delta.
%   f: Flex (passed rec)
%   eta: real[1] (passed a plain number)
%   etad: real[1] (passed a plain number)
%   returns pull: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    pull = 0;
    pull = ((((2 * f.zeta) * f.omega) * etad) + ((f.omega * f.omega) * eta));
end
